# Session Summary projection: make pending debounce drainable and preserve failed work.
Path('packages/projection-session/src/summary-plugin.ts').write_text('''import type { Plugin } from '@deepseek-ai/cordis'\nimport type { ProjectionDefinition, ProjectionScope } from '@agent-lens/core'\nimport type { AgentLensContext } from '@agent-lens/runtime-cordis'\n\nexport const SESSION_SUMMARY_PROJECTION_ID = 'session-summary'\nconst REBUILD_DEBOUNCE_MS = 500\n\nfunction logicalSessionIdFromScope(scope?: ProjectionScope): string | undefined {\n  if (scope?.subjectType !== 'logical-session') return undefined\n  return scope.subjectId\n}\n\nconst applySessionSummaryProjection: Plugin.Function<void> = (ctx: AgentLensContext) => {\n  const store = ctx.storage.sessionSummaryProjection\n  if (!store) return\n\n  const pending = new Set<string>()\n  let timer: ReturnType<typeof setTimeout> | undefined\n  let flushPromise: Promise<void> | undefined\n\n  const schedule = () => {\n    if (timer || flushPromise || pending.size === 0) return\n    timer = setTimeout(() => {\n      timer = undefined\n      void flush().catch(error => {\n        console.error('[AgentLens] session summary projection refresh failed', error)\n      })\n    }, REBUILD_DEBOUNCE_MS)\n  }\n\n  const runPending = async () => {\n    while (pending.size > 0) {\n      const ids = [...pending]\n      pending.clear()\n      for (let index = 0; index < ids.length; index += 1) {\n        const logicalSessionId = ids[index]!\n        const scope = { subjectType: 'logical-session', subjectId: logicalSessionId }\n        try {\n          ctx.emit('projection/invalidated', {\n            projectionId: SESSION_SUMMARY_PROJECTION_ID,\n            ...scope,\n          })\n          await ctx.projections.rebuild(SESSION_SUMMARY_PROJECTION_ID, scope)\n        } catch (error) {\n          for (const remaining of ids.slice(index)) pending.add(remaining)\n          throw error\n        }\n      }\n    }\n  }\n\n  async function flush(): Promise<void> {\n    if (timer) {\n      clearTimeout(timer)\n      timer = undefined\n    }\n    if (flushPromise) {\n      await flushPromise\n      if (pending.size > 0) await flush()\n      return\n    }\n    if (pending.size === 0) return\n\n    const current = runPending()\n    flushPromise = current\n    try {\n      await current\n    } finally {\n      if (flushPromise === current) flushPromise = undefined\n      schedule()\n    }\n  }\n\n  const definition: ProjectionDefinition = {\n    id: SESSION_SUMMARY_PROJECTION_ID,\n    async rebuild(scope) {\n      const logicalSessionId = logicalSessionIdFromScope(scope)\n      await store.rebuild(logicalSessionId ? { logicalSessionId } : {})\n      ctx.emit('projection/rebuilt', {\n        projectionId: SESSION_SUMMARY_PROJECTION_ID,\n        ...(scope?.subjectType ? { subjectType: scope.subjectType } : {}),\n        ...(scope?.subjectId ? { subjectId: scope.subjectId } : {}),\n      })\n    },\n    flush,\n  }\n\n  ctx.projections.register(definition)\n\n  ctx.on('observation/committed', event => {\n    if (event.status !== 'created') return\n    pending.add(event.logicalSessionId)\n    schedule()\n  })\n}\n\napplySessionSummaryProjection.inject = ['storage', 'projections']\n\nexport const sessionSummaryProjectionPlugin = applySessionSummaryProjection\n''')

# Daemon readiness helper + focused regression tests.
Path('apps/daemon/src/projection-readiness.ts').write_text('''import type {\n  CheckpointRepository,\n  ProjectionService,\n  SessionSummaryProjectionStore,\n} from '@agent-lens/core'\nimport { SESSION_SUMMARY_PROJECTION_ID } from '@agent-lens/projection-session'\n\nconst CHECKPOINT_SCOPE = 'runtime'\nconst CHECKPOINT_KEY = 'projection:session-summary:clean-v1'\n\ninterface SessionSummaryCleanMarker {\n  version: 1\n  clean: true\n  markedAt: string\n}\n\nexport interface ProjectionReadinessStorage {\n  checkpoints: Pick<CheckpointRepository, 'get' | 'set' | 'clear'>\n  sessionSummaryProjection?: Pick<SessionSummaryProjectionStore, 'isMaterialized'>\n}\n\nexport async function beginSessionSummaryProjectionRun(\n  storage: ProjectionReadinessStorage,\n): Promise<boolean> {\n  const marker = await storage.checkpoints.get<SessionSummaryCleanMarker>(\n    CHECKPOINT_SCOPE,\n    CHECKPOINT_KEY,\n  )\n\n  // Mark this process dirty before any source can commit new Canonical data. A crash\n  // anywhere after this point therefore forces a conservative rebuild next start.\n  await storage.checkpoints.clear(CHECKPOINT_SCOPE, CHECKPOINT_KEY)\n\n  if (marker?.version !== 1 || marker.clean !== true) return false\n  const projection = storage.sessionSummaryProjection\n  return projection ? projection.isMaterialized() : false\n}\n\nexport async function markSessionSummaryProjectionClean(\n  storage: ProjectionReadinessStorage,\n  projections: Pick<ProjectionService, 'flush'>,\n): Promise<void> {\n  await projections.flush(SESSION_SUMMARY_PROJECTION_ID)\n  await storage.checkpoints.set<SessionSummaryCleanMarker>(CHECKPOINT_SCOPE, CHECKPOINT_KEY, {\n    version: 1,\n    clean: true,\n    markedAt: new Date().toISOString(),\n  })\n}\n\nexport const projectionReadinessInternals = {\n  CHECKPOINT_SCOPE,\n  CHECKPOINT_KEY,\n}\n''')

Path('apps/daemon/src/projection-readiness.test.ts').write_text('''import assert from 'node:assert/strict'\nimport test from 'node:test'\nimport type { CheckpointRepository } from '@agent-lens/core'\nimport {\n  beginSessionSummaryProjectionRun,\n  markSessionSummaryProjectionClean,\n  projectionReadinessInternals,\n} from './projection-readiness.js'\n\nfunction checkpoints(initial?: unknown) {\n  const values = new Map<string, unknown>()\n  const id = `${projectionReadinessInternals.CHECKPOINT_SCOPE}:${projectionReadinessInternals.CHECKPOINT_KEY}`\n  if (initial !== undefined) values.set(id, initial)\n  const repository: CheckpointRepository = {\n    async get<T>(scope: string, key: string): Promise<T | null> {\n      return (values.get(`${scope}:${key}`) as T | undefined) ?? null\n    },\n    async set<T>(scope: string, key: string, value: T): Promise<void> {\n      values.set(`${scope}:${key}`, value)\n    },\n    async clear(scope: string, key: string): Promise<void> {\n      values.delete(`${scope}:${key}`)\n    },\n  }\n  return { repository, values, id }\n}\n\ntest('clean previous shutdown may reuse a materialized projection and immediately marks this run dirty', async () => {\n  const state = checkpoints({ version: 1, clean: true, markedAt: '2026-08-26T00:00:00.000Z' })\n  const reusable = await beginSessionSummaryProjectionRun({\n    checkpoints: state.repository,\n    sessionSummaryProjection: { async isMaterialized() { return true } },\n  })\n  assert.equal(reusable, true)\n  assert.equal(state.values.has(state.id), false)\n})\n\ntest('unclean previous shutdown forces rebuild', async () => {\n  const state = checkpoints()\n  const reusable = await beginSessionSummaryProjectionRun({\n    checkpoints: state.repository,\n    sessionSummaryProjection: { async isMaterialized() { return true } },\n  })\n  assert.equal(reusable, false)\n})\n\ntest('clean marker cannot reuse a missing projection', async () => {\n  const state = checkpoints({ version: 1, clean: true, markedAt: '2026-08-26T00:00:00.000Z' })\n  const reusable = await beginSessionSummaryProjectionRun({\n    checkpoints: state.repository,\n    sessionSummaryProjection: { async isMaterialized() { return false } },\n  })\n  assert.equal(reusable, false)\n  assert.equal(state.values.has(state.id), false)\n})\n\ntest('controlled shutdown flushes the projection before writing the clean marker', async () => {\n  const state = checkpoints()\n  const order: string[] = []\n  const originalSet = state.repository.set.bind(state.repository)\n  state.repository.set = async <T>(scope: string, key: string, value: T): Promise<void> => {\n    order.push('mark')\n    await originalSet(scope, key, value)\n  }\n  await markSessionSummaryProjectionClean(\n    { checkpoints: state.repository },\n    { async flush() { order.push('flush') } },\n  )\n  assert.deepEqual(order, ['flush', 'mark'])\n  assert.equal((state.values.get(state.id) as { clean: boolean }).clean, true)\n})\n\ntest('flush failure never writes a clean marker', async () => {\n  const state = checkpoints()\n  await assert.rejects(() => markSessionSummaryProjectionClean(\n    { checkpoints: state.repository },\n    { async flush() { throw new Error('flush failed') } },\n  ), /flush failed/)\n  assert.equal(state.values.has(state.id), false)\n})\n''')

